  `xmid` int NULL DEFAULT NULL COMMENT '项目id',
  `ddid` int NULL DEFAULT NULL COMMENT '订单id',
  `sqrq` datetime NULL DEFAULT NULL COMMENT '申请日期',
  `fkyt` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款用途',
  `sqje` decimal(15, 5) NULL DEFAULT NULL COMMENT '申请金额',
  `fjid` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件id',
  `bz` varchar(8000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `fkdwdm` int NULL DEFAULT NULL COMMENT '付款单位代码（弃用）',
  `skdwdm` int NULL DEFAULT NULL COMMENT '收款单位代码(弃用)',
  `spzt` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '2' COMMENT '审批状态（已审批、未审批）',
  `jbr` int NULL DEFAULT NULL COMMENT '经办人',
  `jbr_spsj` datetime NULL DEFAULT NULL COMMENT '经办人审批时间',
  `xmfzr` int NULL DEFAULT NULL COMMENT '项目负责人',
  `xmfzr_spsj` datetime NULL DEFAULT NULL COMMENT '项目负责人审批时间',
  `fzjl` int NULL DEFAULT NULL COMMENT '副总经理',
  `fzjl_spsj` datetime NULL DEFAULT NULL COMMENT '副总经理审批时间',
  `zjl` int NULL DEFAULT NULL COMMENT '总经理',
  `zjl_spsj` datetime NULL DEFAULT NULL COMMENT '总经理审批时间',
  `lrrydm` int NULL DEFAULT NULL COMMENT '录入人员代码',
  `lrsj` datetime NULL DEFAULT NULL COMMENT '录入时间',
  `xgrydm` int NULL DEFAULT NULL COMMENT '修改人员代码',
  `xgsj` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `yxbz` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '有效标志（1有效、0无效）',
  PRIMARY KEY (`fksqid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7061 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '付款申请表' ROW_FORMAT = Dynamic;

