INSERT INTO `core_order_info` VALUES (5547, 'D-②吴55.1', 22, '01', '透水混凝土', '原订单金额：257643.00', '2021-04-18', 299074.00000, 299074.00000, '肖佳', '13482455065', '348,349,370,371', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', NULL, NULL, NULL, '花展透水混凝土部分：\n厚度（10+5）：1555平方*166=258130\n厚度（5）：127平方*100=12700\n厚度（10面层）：85.9*150=12885\n\n未喷漆（1555+127+85.9）*-20=-35358\n\n后增蚂蚁乐园喷涂，1449平方*35元/平方=50715元\n\n以上结算价299072元\n');
INSERT INTO `core_order_info` VALUES (5548, 'D-②吴56.1', 11, '01', '透水混凝土', '订单原金额349444.00，2022/10/13对账结算金额为498371.00，2022/10/18蒋逸就订单金额进行修改为结算金额', '2021-04-18', 498371.00000, 498371.00000, '肖佳', '13482455065', '367,368', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', NULL, NULL, NULL, '5公分单价100元，面积1147平方；\n8公分单价112元，面积3283平方\n材料超出21.3立方，单方750元/m³\n6000元抢工费，现场已付，不进入本结算\n\n以上合计：498371');
INSERT INTO `core_order_info` VALUES (5549, 'D-②吴56.2', 14, '01', '透水混凝土', '21解放路绿地项目结算金额为349561元，已支付310384元，本次申请39177元。', '2021-04-24', 349561.00000, 349561.00000, '肖佳', '13482455065', '365,366', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', NULL, NULL, NULL, '透水混凝土工艺，总面积：面层1757.27平方，底层1860.23平方，5公分厚度208.38平方，\n样板段：15+5,：15cm底层为245.66平方，单价：131元，245.66*131=32181.46；\n面层:(1757.27+208.38)*75=147423.75\n大区：12+5：底层1860.23-245.66=1614.57，\n1614.57*100=161457\n另：超厚度加7500元，后画图+模具1000元\n\n合计：349561');
INSERT INTO `core_order_info` VALUES (5550, 'D-②吴57.1', 18, '01', '透水混凝土', '21崇明1花博会结算金额为32232元。', '2021-04-18', 32232.00000, 32232.00000, '肖佳', '13482455065', '350,351,352', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', NULL, NULL, NULL, '原定面积，200平方\n实际施工261平方');
INSERT INTO `core_order_info` VALUES (5551, 'D-②吴58.1', 21, '01', '透水混凝土', '21上植花展拜石露骨料结算金额为33099元。', '2021-04-18', 33099.00000, 33099.00000, '肖佳', '13482455065', '353,354', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', NULL, NULL, NULL, '原5CM透水，结算改为露骨料4CM+4CM\n结算金额：177*187=33099元');
INSERT INTO `core_order_info` VALUES (5552, 'D-②左58.2', 13, '01', '透水混凝土', '21三四号桥项目结算金额为109598元，已支付60000元，本次申请49598元。', '2021-06-23', 109598.00000, 109598.00000, '肖佳', '13482455065', '355,356', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', NULL, NULL, NULL, '原定0.6CM厚，实际2.1CM厚\n原定单价194元/平方\n结算单价344元/平方\n实际施工面积318.6*344=109598');
INSERT INTO `core_order_info` VALUES (5553, 'D-②向58.3', 11, '01', '透水混凝土', '原订单金额244500元，最终结算价位209695元。', '2021-11-26', 209695.00000, 209695.00000, '肖佳', '13482455065', '358,359,360', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', NULL, NULL, NULL, '（松果乐园）陶粒单价150元/平方，面积372.8平方，150*372.8=55920元；\n水洗石台阶180元/米，81.1米，170*81.1=13770元；\n水洗石花坛230元/平方，面积118.1平方，230*118.1=27163元\n水生态项目 水洗石铺装535平方*145元/平方=77575（原定165元/平方，因厚度不到，减至145元/平方）\n翻边255米，单价:150元，255*150=38250\n多次进场费：2000元\n扣除污染押金：-5000\n合计：209695');
