INSERT INTO `core_order_info` VALUES (7479, 'D-2022040802', 68, '09', '008', '', '2022-04-07', 70000.00000, NULL, '何伟波', '13588598115', '150151', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', '', '', '', '生活区伙食（暂定7万）\n3月伙食：朱进、袁航峰，总餐数99餐，99*15元/餐=1485元\n4月伙食：何伟波、朱进、蒋伟明、陈杨勇、袁航峰、楼灿苗、王云超、卞海斌，总餐数480餐，480*15元/餐=7200元\n5月伙食：何伟波、蒋伟明、陈杨勇、朱进、楼灿苗、袁航峰、宣伟光、何伟明、王云超、俞海宾、陈孝潮、潘秋生、陈伯丰、卞海斌、宣培国、陈杨雷、楼伯贤、何利平、张配冬，总餐数910餐，910*15元/餐=13650元\n6月伙食：4740\n7月伙食：2595');
