INSERT INTO `core_order_info` VALUES (7481, 'D-2022040804', 71, '11', '008', '海之花屋顶疫情防控封闭施工期间4月7日伙食预支工资：陈煌欣、潘秋生、陈孝潮、陈伯丰、宣伟光、何伟明、宣培国、俞海宾，共计8个人，每个人1000元，费用由梁锋招行项目卡支付给工人代表陈煌欣，由陈煌欣给到各个工人\n海之花屋顶疫情防控封闭施工期间5月3日伙食预支工资：陈煌欣、潘秋生、陈孝潮、陈伯丰、宣伟光、何伟明、宣培国、俞海宾，共计8个人，每个人1000元，费用由梁锋招行项目卡支付给陈煌欣，由陈煌欣发给到各个工人', '2022-04-07', 16000.00000, 16000.00000, '何伟波', '13588598115', '15', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', '', '梁锋', '', '2022年度海之花-屋面景观项目内申请的工人预支工资（梁锋项目卡支付），项目转入2022年工程部工人工资，原订单以预支工资16000.00元金额结束订单。');
