INSERT INTO `core_order_info` VALUES (8046, 'D-2023042401', 87, '17', '008', '24年乐活合和项目机械费用合计：84万元，24年最终结算优惠85550元，最终金额为：754450元。', '2023-04-23', 754450.00000, NULL, '陈标标', '13301659932', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', '', '蒋伟明', '', '乐活机械协议\n供应商：陈标标\n价格：12元/平方，暂定6万平方，合计暂定72万，含3%发票\n结算面积：按实际实施面积（保留草坪区域不算面积）\n现场施工员：白远远（常驻），其余根据项目需要安排\n付款方式：按月支付生活费，工程竣工付至70%\n费用包含：施工过程中一切机械费。\n如：①包含前期的清理挖机、镐头机、铲车、驳运汽车等，②施工过程中土建、绿化、水电等专业所用挖机、吊车、铲车、驳运汽车等\n施工过程中原则上不发生签单');
INSERT INTO `core_order_info` VALUES (8047, 'D-2023042402', 87, '18', '008', '乐活水电人工协议：\n供应商：陈浩飞\n价格：按5.5元/平方，暂定9万平方，合计暂定金额50万，含开苗木票税金\n现场施工员：孙工（常驻），其余根据项目需要安排\n付款方式：每月按考勤支付生活费，工程竣工付至80%，甲方结算完成付清\n费用包含：①水电施工所有人工费，②拆除并放置现有灯具、线路，③配合制作工程竣工资料，施工过程中原则上不发生点工', '2023-04-23', 500000.00000, NULL, '陈浩飞', '13588405975', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', '', '蒋伟明', '', '');
