INSERT INTO `core_order_info` VALUES (8215, 'D-2023080301', 87, '03', '008', '乐活工地报价\n①苗木移植费用单价5元/1平方\n移植乔木、灌木、球类，清表地被小苗及草皮\n包括死树清理、树枝垃圾堆放至施工场地内指定位置及外运装车卸车。\n②种植费用30元/1平方\n种植乔木、灌木、球类地被草皮(含少量花境)及加施泥碳、土壤改良地形细整理，清检石块粉碎树枝垃圾清理至场地内指定位置\n按工程合同 竣工日期计算。包含施工养护至工程完工两个月结束，\n(工地施工延期养护费用按月另算一个月1平方不少于1元)\n乔木、灌木成活率达95%\n球类、地被成活率达98%\n备注:所有进场苗木必须达到验收标准\n③养护期间无水源地段须 提供供水措施\n④不包含机械费\n⑤不含开苗木票，如果一定要开苗木票须加3个点税金。', '2023-08-02', 1000000.00000, NULL, '刘克圣', '13817560488', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', '', '', '', '');
