INSERT INTO `core_order_info_copy可删` VALUES (7480, 'D-2022040803', 66, '09', '008', '生活区伙食（暂按6万做订单）：\n3月伙食：蒋伟明、陈杨勇、李萍、楼灿苗、宣伟光、何伟明、王云超、潘秋生、卞海斌、其他，总餐数473餐，473*15元/餐=7095元\n4月伙食：无\n5月伙食：李萍，18餐，18*15=270元\n6月伙食：153餐，153*15=2295元\n7月伙食：5385', '2022-04-07', 31470.00000, 31470.00000, '何伟波', '13588598115', '153', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', '', '', '', '22年度（22年2月-23年1月）文耀路景观项目伙食费共计：31470.00，23年度（23年2月-24年1月）开始伙食费不在每月拆分到项目，直接在最后整年度分摊到项目，故本订单使用至22年1月，结算金额为31470.00');
