INSERT INTO `core_payment_request_info` VALUES (4372, 'S-202308030101', 87, 8215, '2023-08-03 00:00:00', '乐活和合项目-绿化分包刘克圣暂定总额为100万，本次申请支付10万', 100000.00000, '', '乐活工地报价\n①苗木移植费用单价5元/1平方\n移植乔木、灌木、球类，清表地被小苗及草皮\n包括死树清理、树枝垃圾堆放至施工场地内指定位置及外运装车卸车。\n②种植费用30元/1平方\n种植乔木、灌木、球类地被草皮(含少量花境)及加施泥碳、土壤改良地形细整理，清检石块粉碎树枝垃圾清理至场地内指定位置\n按工程合同 竣工日期计算。包含施工养护至工程完工两个月结束，\n(工地施工延期养护费用按月另算一个月1平方不少于1元)\n乔木、灌木成活率达95%\n球类、地被成活率达98%\n备注:所有进场苗木必须达到验收标准\n③养护期间无水源地段须 提供供水措施\n④不包含机械费\n⑤不含开苗木票，如果一定要开苗木票须加3个点税金。', NULL, NULL, '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 10, '2023-08-03 17:51:40', NULL, NULL, '1');
